('prod-104', 'Raw Coorg Forest Wild Honey', 'Groceries', 'shop-1', 450.00, '563.00', 20, 3, 4.9, 52, 'Unprocessed, multi-floral raw honey collected by tribal cooperatives in the Western Ghats forests. Naturally crystallized and unheated.', '{"Origin":"Coorg, Karnataka","Purity":"100% Raw Unpasteurized","Net Weight":"400g","FSSAI Certified":"Yes"}'::jsonb, '["honey","organic","sweetener","immunity"]'::jsonb, 'assets/product-images/prod-104.jpg', TRUE, TRUE, 'approved'),
